/**
 * The words that open a word's private note when the desktop app saved it:
 * "Seen in Tears of Steel · 0:50" from the video player
 * (features/player/model/words.ts `seenIn`), "Seen in Microsoft Word" from
 * the shortcut (written by the desktop core: lexpad_desktop
 * `src/lib/compose.ts`). The word page (features/word/origin.ts) and the Watch
 * page (features/watch/videoWords.ts) read the note back by these words, so
 * the core and this app must change them together.
 *
 * This is a stand-in: the API's `source` has no value for "from a video" or
 * "from another app" yet (manual, ai, import, shared, assistant). The proper
 * fix is a source (or a "seen in" field) on the server; until then the note's
 * first words are what say where a word was met.
 */
export const SEEN_IN = 'Seen in ';
